create extension if not exists pgcrypto;
create type public.profile_role as enum ('admin');
create type public.raffle_status as enum ('draft','active','closed','finished');
create type public.number_status as enum ('available','pending','confirmed','blocked');
create type public.reservation_status as enum ('pending','confirmed','rejected','expired','cancelled');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, role profile_role not null default 'admin', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.customers (id uuid primary key default gen_random_uuid(), name text not null, phone text not null, phone_normalized text not null unique, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.raffles (id uuid primary key default gen_random_uuid(), title text not null, slug text not null unique, description text not null default '', image_path text, prize_name text not null, price_per_number numeric(12,2) not null check (price_per_number > 0), number_start integer not null default 0, number_end integer not null check (number_end >= number_start), sales_close_at timestamptz not null, draw_at timestamptz not null, draw_method text not null default 'Lotería', whatsapp_number text, payment_instructions text, reservation_minutes integer not null default 15 check (reservation_minutes between 1 and 1440), status raffle_status not null default 'draft', winner_number integer, winner_customer_id uuid references public.customers(id), winner_reservation_id uuid, winner_selected_at timestamptz, prize_delivered_at timestamptz, created_by uuid references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.raffle_numbers (id uuid primary key default gen_random_uuid(), raffle_id uuid not null references public.raffles(id) on delete cascade, number integer not null, number_display text not null, status number_status not null default 'available', blocked_reason text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(raffle_id, number));
create table public.reservations (id uuid primary key default gen_random_uuid(), code text not null unique, raffle_id uuid not null references public.raffles(id), customer_id uuid not null references public.customers(id), status reservation_status not null default 'pending', price_per_number numeric(12,2) not null, quantity integer not null check (quantity > 0), total numeric(12,2) not null, reserved_until timestamptz not null, confirmed_at timestamptz, rejected_at timestamptz, expired_at timestamptz, confirmed_by uuid references auth.users(id), rejected_by uuid references auth.users(id), rejection_reason text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.reservation_numbers (id uuid primary key default gen_random_uuid(), reservation_id uuid not null references public.reservations(id) on delete cascade, raffle_number_id uuid not null references public.raffle_numbers(id), created_at timestamptz not null default now(), unique(reservation_id, raffle_number_id));
alter table public.raffles add constraint winner_reservation_fk foreign key (winner_reservation_id) references public.reservations(id);
create index raffle_numbers_raffle_status_idx on public.raffle_numbers(raffle_id,status); create index reservations_status_idx on public.reservations(status); create index reservations_customer_idx on public.reservations(customer_id); create index customers_phone_idx on public.customers(phone_normalized);
create or replace function public.is_admin() returns boolean language sql security definer set search_path = public as $$ select exists(select 1 from public.profiles where id = auth.uid() and role = 'admin'); $$;
alter table public.profiles enable row level security; alter table public.customers enable row level security; alter table public.raffles enable row level security; alter table public.raffle_numbers enable row level security; alter table public.reservations enable row level security; alter table public.reservation_numbers enable row level security;
create policy "public active raffles" on public.raffles for select using (status in ('active','closed','finished')); create policy "public number states" on public.raffle_numbers for select using (exists(select 1 from public.raffles r where r.id = raffle_id and r.status in ('active','closed','finished'))); create policy "admins manage raffles" on public.raffles for all using (public.is_admin()) with check (public.is_admin()); create policy "admins manage numbers" on public.raffle_numbers for all using (public.is_admin()) with check (public.is_admin()); create policy "admins read customers" on public.customers for select using (public.is_admin()); create policy "admins read reservations" on public.reservations for select using (public.is_admin()); create policy "admins update reservations" on public.reservations for update using (public.is_admin()); create policy "admins read reservation numbers" on public.reservation_numbers for select using (public.is_admin()); create policy "own profile" on public.profiles for select using (id = auth.uid() or public.is_admin());
create or replace function public.create_reservation(p_raffle_id uuid, p_customer_name text, p_customer_phone text, p_selected_numbers integer[]) returns jsonb language plpgsql security definer set search_path = public as $$ declare raffle_row public.raffles; customer_row public.customers; reservation_row public.reservations; normalized_phone text := regexp_replace(p_customer_phone, '[^0-9]', '', 'g'); selected_count integer := coalesce(array_length(p_selected_numbers,1),0); unavailable integer; code_value text; begin if length(trim(p_customer_name)) < 3 or selected_count = 0 then raise exception 'Datos de reserva inválidos'; end if; select * into raffle_row from public.raffles where id = p_raffle_id for update; if raffle_row.status <> 'active' or raffle_row.sales_close_at <= now() then raise exception 'Las ventas están cerradas'; end if; select count(*) into unavailable from public.raffle_numbers where raffle_id = p_raffle_id and number = any(p_selected_numbers) and status <> 'available'; if unavailable > 0 then raise exception 'Uno de los números ya no está disponible'; end if; insert into public.customers(name,phone,phone_normalized) values(trim(p_customer_name),p_customer_phone,normalized_phone) on conflict(phone_normalized) do update set name = excluded.name, phone = excluded.phone, updated_at = now() returning * into customer_row; code_value := 'RF-' || upper(substr(encode(gen_random_bytes(5),'hex'),1,6)); insert into public.reservations(code,raffle_id,customer_id,price_per_number,quantity,total,reserved_until) values(code_value,p_raffle_id,customer_row.id,raffle_row.price_per_number,selected_count,raffle_row.price_per_number * selected_count,now() + make_interval(mins => raffle_row.reservation_minutes)) returning * into reservation_row; insert into public.reservation_numbers(reservation_id,raffle_number_id) select reservation_row.id,id from public.raffle_numbers where raffle_id = p_raffle_id and number = any(p_selected_numbers); update public.raffle_numbers set status = 'pending', updated_at = now() where raffle_id = p_raffle_id and number = any(p_selected_numbers); return jsonb_build_object('reservation_id',reservation_row.id,'reservation_code',reservation_row.code,'quantity',reservation_row.quantity,'total',reservation_row.total,'reserved_until',reservation_row.reserved_until,'raffle_title',raffle_row.title); end; $$;
create or replace function public.release_expired_reservations() returns integer language plpgsql security definer set search_path = public as $$ declare released integer; begin update public.reservations set status='expired', expired_at=now(), updated_at=now() where status='pending' and reserved_until <= now(); get diagnostics released = row_count; update public.raffle_numbers rn set status='available', updated_at=now() where status='pending' and not exists(select 1 from public.reservation_numbers rns join public.reservations r on r.id=rns.reservation_id where rns.raffle_number_id=rn.id and r.status='pending'); return released; end; $$;
create or replace function public.confirm_reservation(p_reservation_id uuid) returns void language plpgsql security definer set search_path = public as $$ begin if not public.is_admin() then raise exception 'No autorizado'; end if; update public.reservations set status='confirmed',confirmed_at=now(),confirmed_by=auth.uid(),updated_at=now() where id=p_reservation_id and status='pending'; if not found then raise exception 'La reserva no está pendiente'; end if; update public.raffle_numbers set status='confirmed',updated_at=now() where id in (select raffle_number_id from public.reservation_numbers where reservation_id=p_reservation_id); end; $$;
create or replace function public.reject_reservation(p_reservation_id uuid,p_reason text default null) returns void language plpgsql security definer set search_path = public as $$ begin if not public.is_admin() then raise exception 'No autorizado'; end if; update public.reservations set status='rejected',rejected_at=now(),rejected_by=auth.uid(),rejection_reason=p_reason,updated_at=now() where id=p_reservation_id and status='pending'; if not found then raise exception 'La reserva no está pendiente'; end if; update public.raffle_numbers set status='available',updated_at=now() where id in (select raffle_number_id from public.reservation_numbers where reservation_id=p_reservation_id); end; $$;
grant execute on function public.create_reservation(uuid,text,text,integer[]) to anon,authenticated; grant execute on function public.release_expired_reservations() to authenticated; grant execute on function public.confirm_reservation(uuid) to authenticated; grant execute on function public.reject_reservation(uuid,text) to authenticated;